package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaLock sync.RWMutex
	metadata = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata. This overrides the packaged metadata at runtime.
//
// Since: 2.2
func SetMetadata(m fyne.AppMetadata) {
	metaLock.Lock()
	defer metaLock.Unlock()
	metadata = m
}

func getMetadata() fyne.AppMetadata {
	metaLock.RLock()
	defer metaLock.RUnlock()
	return metadata
}

