package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DarkTheme(), err
	}

	jt := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse Colors (variant-independent)
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, hexVal := range colors {
			if hexStr, ok := hexVal.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse Colors-dark (dark variant specific)
	if colors, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, hexVal := range colors {
			if hexStr, ok := hexVal.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colorsDark[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse Colors-light (light variant specific)
	if colors, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, hexVal := range colors {
			if hexStr, ok := hexVal.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colorsLight[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse Sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, val := range sizes {
			if floatVal, ok := val.(float64); ok {
				jt.sizes[fyne.ThemeSizeName(name)] = float32(floatVal)
			}
		}
	}

	// Parse Fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, uriVal := range fonts {
			if uriStr, ok := uriVal.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					jt.fonts[style] = &uriResource{uri: uri}
				}
			}
		}
	}

	// Parse Icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, uriVal := range icons {
			if uriStr, ok := uriVal.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					jt.icons[fyne.ThemeIconName(name)] = &uriResource{uri: uri}
				}
			}
		}
	}

	return jt, nil
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports 3, 4, 6, and 8 digit hex formats with or without '#' prefix.
func parseHexColor(hex string) (color.Color, error) {
	// Remove '#' prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3:
		// RGB: "abc" → 0xaa 0xbb 0xcc 0xff
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
	case 4:
		// RGBA: "abcd" → 0xaa 0xbb 0xcc 0xdd
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)
	case 6:
		// RRGGBB: "a1b2c3" → 0xa1 0xb2 0xc3 0xff
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]
	case 8:
		// RRGGBBAA: "a1b2c3f4" → 0xa1 0xb2 0xc3 0xf4
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]
		a = vals[3]
	default:
		return color.Transparent, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses hex digits in groups of digitsPer
func parseHexDigits(hex string, digitsPer int) ([]uint8, error) {
	if len(hex)%digitsPer != 0 {
		return nil, fmt.Errorf("invalid hex length")
	}
	result := make([]uint8, len(hex)/digitsPer)
	for i := 0; i < len(result); i++ {
		substr := hex[i*digitsPer : (i+1)*digitsPer]
		val, err := strconv.ParseUint(substr, 16, 8)
		if err != nil {
			return nil, err
		}
		result[i] = uint8(val)
	}
	return result, nil
}

// jsonTheme implements fyne.Theme by wrapping JSON-defined overrides
type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[string]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific first
	if variant == fyne.VariantDark {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	} else if variant == fyne.VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic Colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to default theme
	return DarkTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else if style.Monospace {
		key = "monospace"
	} else {
		key = "regular"
	}

	if res, ok := t.fonts[key]; ok {
		return res
	}
	return DarkTheme().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if res, ok := t.icons[name]; ok {
		return res
	}
	return DarkTheme().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	return DarkTheme().Size(name)
}

// uriResource wraps a URI to implement fyne.Resource
type uriResource struct {
	uri fyne.URI
}

func (r *uriResource) Name() string {
	return r.uri.Name()
}

func (r *uriResource) Content() []byte {
	// For JSON themes, we defer content loading to the renderer
	// This is a placeholder implementation
	return nil
}

